#!/usr/bin/env python3

"""
Script to reproduce the bug with mocked classmethod in oop-ext.
"""

import sys
import os

# Add the src directory to the path so we can import oop_ext
sys.path.insert(0, os.path.join(os.path.dirname(__file__), 'src'))

from oop_ext.interface import Interface, ImplementsInterface, AssertImplements


def testRequiresDeclarationBug(mocker=None):
    """Test that reproduces the bug with mocked classmethod."""

    class IFoo(Interface):
        @classmethod
        def foo(cls):
            ""

    @ImplementsInterface(IFoo)
    class FooImplementation:
        @classmethod
        def foo(cls):
            ""

    # If mocker is provided, simulate the spy behavior
    if mocker is not None:
        # This simulates what mocker.spy does - it replaces the method with a MagicMock
        from unittest.mock import MagicMock
        mock_foo = MagicMock()
        FooImplementation.foo = mock_foo

    print("Testing AssertImplements with requires_declaration=True...")
    try:
        AssertImplements(FooImplementation, IFoo, requires_declaration=True)
        print("SUCCESS: AssertImplements passed!")
        return True
    except AssertionError as e:
        print(f"FAILED: {e}")
        return False


def testWithoutMock():
    """Test without mocking to make sure normal case works."""
    print("\n=== Testing without mock ===")

    class IFoo(Interface):
        @classmethod
        def foo(cls):
            ""

    @ImplementsInterface(IFoo)
    class FooImplementation:
        @classmethod
        def foo(cls):
            ""

    try:
        AssertImplements(FooImplementation, IFoo, requires_declaration=True)
        print("SUCCESS: Normal case works correctly")
        return True
    except AssertionError as e:
        print(f"FAILED: Normal case failed unexpectedly: {e}")
        return False


def testWithMockLikeBehavior():
    """Test with mock-like behavior to reproduce the issue."""
    print("\n=== Testing with mock-like behavior ===")

    class IFoo(Interface):
        @classmethod
        def foo(cls):
            ""

    @ImplementsInterface(IFoo)
    class FooImplementation:
        @classmethod
        def foo(cls):
            ""

    # Simulate what happens when unittest.mock creates a MagicMock for a classmethod
    from unittest.mock import MagicMock
    original_foo = FooImplementation.foo
    mock_foo = MagicMock()
    FooImplementation.foo = mock_foo

    print(f"Original foo type: {type(original_foo)}")
    print(f"Mock foo type: {type(mock_foo)}")
    print(f"isfunction on original: {hasattr(original_foo, '__func__') and callable(original_foo.__func__)}")
    print(f"isfunction on mock: {hasattr(mock_foo, '__func__') and callable(mock_foo.__func__)}")
    print(f"ismethod on original: {callable(original_foo)}")
    print(f"ismethod on mock: {callable(mock_foo)}")

    try:
        AssertImplements(FooImplementation, IFoo, requires_declaration=True)
        print("SUCCESS: Mock case works correctly")
        success = True
    except AssertionError as e:
        print(f"FAILED: Mock case failed as expected: {e}")
        success = False

    # Restore original for cleanup
    FooImplementation.foo = original_foo
    return success


def testIsMethodFunction():
    """Test the _IsMethod function directly."""
    print("\n=== Testing _IsMethod function directly ===")

    # Import the internal _IsMethod function
    from oop_ext.interface._interface import _IsMethod
    from unittest.mock import MagicMock

    class TestClass:
        @classmethod
        def test_classmethod(cls):
            pass

    # Test with real classmethod
    real_method = TestClass.test_classmethod
    print(f"_IsMethod(real_classmethod): {_IsMethod(real_method)}")
    print(f"type(real_classmethod): {type(real_method)}")
    print(f"inspect.isfunction(real_classmethod): {hasattr(real_method, '__func__') and callable(real_method.__func__)}")
    import inspect
    print(f"inspect.isfunction(real_method): {inspect.isfunction(real_method)}")
    print(f"inspect.ismethod(real_method): {inspect.ismethod(real_method)}")

    # Test with mock
    mock_method = MagicMock()
    print(f"_IsMethod(mock): {_IsMethod(mock_method)}")
    print(f"type(mock): {type(mock_method)}")
    print(f"inspect.isfunction(mock): {inspect.isfunction(mock_method)}")
    print(f"inspect.ismethod(mock): {inspect.ismethod(mock_method)}")
    from oop_ext.foundation.types_ import Method
    print(f"isinstance(mock, Method): {isinstance(mock_method, Method)}")


if __name__ == "__main__":
    print("Reproducing the classmethod mock bug...")

    # Test normal case first
    testWithoutMock()

    # Test with mock behavior
    testWithMockLikeBehavior()

    # Test the _IsMethod function directly
    testIsMethodFunction()

    print("\nDone.")

